package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object EarningCards {
    private val T = Track.EARNING
    val cards: List<Card> = listOf(
        // ---------- Level 1: Rookie ----------
        concept("ea-human-capital", T, 1, "Early in life, what is usually your single biggest financial asset?",
            "You. Your skills, health and contacts (\"human capital\") will earn you decades of income. At 25 that future pay is worth far more than any savings or shamba you own, so feeding it pays off.",
            source = "Becker, Human Capital, 1964"),
        quiz("ea-two-levers", T, 1, "Your savings gap is the space between what comes in and what goes out. Which lever has no ceiling?",
            listOf("Raising income", "Cutting costs", "Skipping meals", "Delaying rent"), 0,
            "You can only cut spending down to the basics, but income has no fixed top. Most people need both levers, and the earning lever grows with skill.",
            source = "Morph Academy"),
        concept("ea-gross-net", T, 1, "What's the difference between gross pay and net pay?",
            "Gross is the salary on your contract. Net is what lands in your account after PAYE, NSSF, SHIF and the Housing Levy. Always plan your budget on net, and compare job offers on both.",
            source = "KRA"),
        quiz("ea-payslip-deductions", T, 1, "Which of these is NOT a standard deduction on a Kenyan payslip?",
            listOf("M-Pesa transaction fees", "PAYE", "SHIF", "NSSF"), 0,
            "PAYE (income tax), NSSF (pension), SHIF (health) and the Affordable Housing Levy come off most payslips. M-Pesa fees are your own spending, not a payroll deduction.",
            source = "KRA, 2026", tryThis = "Look at your last payslip and name every deduction on it."),
        concept("ea-active-passive", T, 1, "What's the difference between active and passive income?",
            "Active income stops when you stop: salary, boda trips, mama mboga sales. Passive income keeps coming with little work: rent, dividends, interest, royalties. Most people build passive income using savings from active income.",
            source = "Morph Academy"),
        quiz("ea-side-hustle-def", T, 1, "Wanjiru works at a bank and bakes cakes for weekend orders. What is the cake business?",
            listOf("A side hustle", "Her main job", "Passive income", "A pension"), 0,
            "A side hustle is extra work alongside your main income. It adds cash and can test a business idea before you leave your job.",
            source = "Morph Academy"),
        quiz("ea-skill-value", T, 1, "Why does a plumber earn more per hour than a car-wash attendant in Nairobi?",
            listOf("Scarcer skill, costlier mistakes", "Plumbers work longer hours", "The law sets their pay", "Plumbing has no competition"), 0,
            "Pay follows how scarce a skill is and how much value or risk it carries. Fewer people can fix a burst pipe, and a bad fix is costly, so clients pay more.",
            source = "Morph Academy"),
        concept("ea-income-streams", T, 1, "Why do many Kenyans keep more than one income stream?",
            "One stream can stop suddenly: layoffs, a sick cow, a slow season. Two or three streams (a job, a small business, chama dividends) smooth the shocks. More streams also means more to manage, so add them one at a time.",
            source = "Morph Academy"),
        quiz("ea-raise-inflation", T, 1, "You get a 5% raise while prices rise 6% in the same year. What happened to your real pay?",
            listOf("It fell about 1%", "It rose 5%", "It rose 11%", "It stayed the same"), 0,
            "Real pay is what your money can buy. If prices rise faster than your pay, you can afford a little less than last year even after a raise.",
            source = "KNBS CPI method"),
        concept("ea-networking", T, 1, "Why does your network matter for earning?",
            "Many jobs and gigs are filled through people who already know your work. A former classmate, a chama member or a past client can open doors a CV can't. Helping others first keeps a network warm.",
            source = "Granovetter, 1973"),
        quiz("ea-time-to-money", T, 1, "Which is the best example of investing in your earning power?",
            listOf("A short course that adds a paid skill", "A new phone on credit", "Weekend betting", "A bigger TV"), 0,
            "Spending that raises what you can earn (skills, tools, certificates) can pay for itself many times. The others are consumption or gambles.",
            source = "Morph Academy"),
        you("ea-you-spend-income", T, 1, "Your yearly spending is about {spend_year}. How much extra income would cover a whole month of it?",
            "A month is about a twelfth of {spend_year}. If a side hustle brought in that much each year, you'd buy back one month of costs, which is one month of freedom. Earning more is how the freedom number shrinks in years, not decades.",
            tryThis = "Check your monthly spending in Patterns.", action = Action.PATTERNS),

        // ---------- Level 2: Hustler ----------
        quiz("ea-hourly-wage", T, 2, "You earn Ksh 60,000 a month for 176 hours of work. What's your rough gross hourly rate?",
            listOf("About Ksh 340", "About Ksh 600", "About Ksh 150", "About Ksh 1,000"), 0,
            "60,000 ÷ 176 hours ≈ Ksh 341 an hour before tax. Knowing this helps you judge side gigs, overtime and whether a long commute is worth it.",
            source = "Morph Academy"),
        quiz("ea-hustle-true-rate", T, 2, "A weekend gig pays Ksh 3,000 for 6 hours, plus 2 hours of matatu travel costing Ksh 400. What's the true hourly rate?",
            listOf("Ksh 325", "Ksh 500", "Ksh 375", "Ksh 433"), 0,
            "Count all the time and all the costs: (3,000 − 400) ÷ 8 hours = Ksh 325 an hour. Travel and prep time quietly shrink many side hustles.",
            source = "Morph Academy"),
        concept("ea-hustle-margin", T, 2, "Kamau sells smokies: Ksh 50 each, costing Ksh 30 to make. He sells 80 a day. What does he really earn?",
            "Profit per smokie is Ksh 20, so 80 × 20 = Ksh 1,600 a day, before rent, permits, gas and spoilage. Revenue (Ksh 4,000) is not income. Always track profit, not sales.",
            source = "Morph Academy", tryThis = "Track one hustle's costs for a week, not just its sales."),
        quiz("ea-pricing-cost-plus", T, 2, "A tailor spends Ksh 800 on fabric and 3 hours on a shirt, and values her time at Ksh 300 an hour. What's the lowest sensible price?",
            listOf("Ksh 1,700", "Ksh 800", "Ksh 1,100", "Ksh 2,400"), 0,
            "Cost-plus pricing: 800 materials + 3 × 300 labour = Ksh 1,700 just to break even on her time. Add a margin on top, or she is working for free.",
            source = "Morph Academy"),
        concept("ea-value-pricing", T, 2, "What is value-based pricing, and when does it beat charging by the hour?",
            "You price by what the result is worth to the client, not by your time. A website that brings a hotel Ksh 500,000 of bookings can fairly cost more than 20 hours × your hourly rate. It works best when the value is clear and measurable.",
            source = "Morph Academy"),
        quiz("ea-raise-vs-cut", T, 2, "Which adds more each year: cutting a Ksh 300 daily lunch to Ksh 200, or a side gig netting Ksh 4,000 every weekend?",
            listOf("The side gig", "The lunch cut", "They're about equal", "Neither adds anything"), 0,
            "The lunch cut saves about 100 × 22 workdays × 12 ≈ Ksh 26,400 a year. The gig nets about 4,000 × 52 ≈ Ksh 208,000. Both help, but earning moves the needle more here.",
            source = "Morph Academy"),
        concept("ea-billable-hours", T, 2, "Why can't a freelancer bill all 2,000 working hours in a year?",
            "Much time goes to finding clients, quoting, admin, learning and gaps between jobs. Many freelancers bill only about half their hours. So if you want Ksh 1.2 million a year from 1,000 billable hours, charge at least Ksh 1,200 an hour.",
            source = "Morph Academy"),
        quiz("ea-pricing-raise", T, 2, "You raise prices 10% and lose 5% of customers. If costs stay the same, what happens to revenue?",
            listOf("It rises about 4.5%", "It falls 5%", "It rises 10%", "It stays the same"), 0,
            "1.10 × 0.95 = 1.045, so revenue rises about 4.5% while you serve fewer customers. Underpricing is common among new hustlers.",
            source = "Morph Academy"),
        concept("ea-portfolio-proof", T, 2, "You have a skill but no clients yet. What's the fastest way to prove you're good?",
            "Show, don't tell. Build two or three sample projects, do a small paid job at a fair price, and collect written reviews. A portfolio and real testimonials beat a long CV for gigs.",
            source = "Morph Academy", tryThis = "Write down three pieces of work you could show a new client today."),
        quiz("ea-quit-math", T, 2, "Your hustle nets Ksh 30,000 a month and your job pays Ksh 70,000 net. What should you check before quitting?",
            listOf("If it can cover all costs for months", "If your friends approve", "If it made money last week", "If you hate your boss"), 0,
            "Quit only when the business can cover your living costs steadily, and you hold an emergency fund for the slow months. Remember the job also brings NSSF, SHIF and steady cash.",
            source = "Morph Academy"),
        concept("ea-ask-for-raise", T, 2, "What should you bring to a raise conversation?",
            "Evidence: results you delivered (in Ksh or numbers), new tasks you took on, and what the market pays for your role. Ask for a specific figure, and pick timing near reviews or after a win.",
            source = "Morph Academy"),
        quiz("ea-overtime-check", T, 2, "Overtime pays Ksh 400 an hour but you'd take a Ksh 150 boda home each late night. Is a 2-hour shift worth it?",
            listOf("Yes: about Ksh 650 extra before tax", "No: you'd lose money", "Only if paid in cash", "Only on weekends"), 0,
            "2 × 400 = 800, minus the Ksh 150 boda = Ksh 650 before tax. Worth it if you value the evening less than that. Pricing your time makes such choices clear.",
            source = "Morph Academy"),

        // ---------- Level 3: Pro ----------
        concept("ea-batna", T, 3, "In salary negotiation, what is your BATNA and why does it matter?",
            "Your Best Alternative To a Negotiated Agreement: what you'll do if this deal fails, such as another offer or staying put. A strong BATNA lets you walk away, which gives you power. Improve it before you negotiate.",
            source = "Fisher & Ury, Getting to Yes, 1981"),
        quiz("ea-anchoring", T, 3, "Research on negotiation finds that the first number put on the table tends to...",
            listOf("Pull the final deal toward it", "Be ignored by the other side", "Always favour the employer", "Only matter in big deals"), 0,
            "First offers act as anchors: final agreements tend to land closer to whoever named a number first. If you know the market rate well, consider anchoring first, slightly high and with reasons.",
            source = "Galinsky & Mussweiler, 2001"),
        quiz("ea-total-package", T, 3, "Offer A: Ksh 120,000 salary. Offer B: Ksh 110,000 plus 10% employer pension match on Ksh 110,000. On cash plus pension, which is larger?",
            listOf("They're about equal", "Offer A by Ksh 10,000", "Offer B by Ksh 21,000", "Offer A by Ksh 21,000"), 0,
            "B's match adds Ksh 11,000, so 110,000 + 11,000 = Ksh 121,000, about equal to A. Then compare medical cover, leave, growth and commute. Look at the whole package, not just the salary line.",
            source = "Morph Academy"),
        concept("ea-job-switch", T, 3, "Why does switching jobs often bring a bigger raise than staying?",
            "A new employer must beat your current pay to win you, while annual raises at the same firm are often small. US data shows switchers usually out-earn stayers, though the gap shrinks when hiring slows. Switching too often can hurt trust, so time it.",
            source = "Atlanta Fed Wage Growth Tracker, 2026", timeSensitive = true),
        quiz("ea-cert-roi", T, 3, "A certification costs Ksh 90,000 and lifts your net pay by Ksh 6,000 a month. Roughly how long until it pays back?",
            listOf("15 months", "6 months", "3 years", "90 months"), 0,
            "90,000 ÷ 6,000 = 15 months. After that, every month is profit. Check that employers really pay more for it before you sign up: ask people in the role.",
            source = "Morph Academy"),
        quiz("ea-platform-fee", T, 3, "Fiverr keeps 20% of each order. To take home Ksh 8,000 from a gig, what should you price it at?",
            listOf("Ksh 10,000", "Ksh 9,600", "Ksh 8,800", "Ksh 8,200"), 0,
            "You keep 80%, so the price must be 8,000 ÷ 0.8 = Ksh 10,000. Adding 20% (Ksh 9,600) falls short. Withdrawal and conversion fees come on top.",
            source = "Fiverr seller terms, 2026", timeSensitive = true),
        concept("ea-online-tax", T, 3, "Do Kenyans owe tax on money earned from Upwork or Fiverr clients abroad?",
            "Yes. Kenyan residents are taxed on income from work done in Kenya, even when the client pays from abroad. Get a KRA PIN, keep records, and declare the income in your annual return by 30 June.",
            source = "KRA, 2026", timeSensitive = true, tryThis = "Log in to iTax and check that your annual return is filed."),
        quiz("ea-tot", T, 3, "A small business with yearly sales between Ksh 1 million and Ksh 25 million can pay Turnover Tax. At what rate?",
            listOf("1.5% of gross sales", "3% of profit", "16% of sales", "30% of profit"), 0,
            "Turnover Tax (TOT) is 1.5% of gross sales, filed monthly on iTax. It's simple, but charged on sales, not profit, so low-margin businesses should compare it with normal income tax.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("ea-counteroffer", T, 3, "You have an outside offer and your boss counters. What's the usual risk of accepting?",
            listOf("Your loyalty may be doubted later", "It's illegal in Kenya", "You lose NSSF", "Your pay falls"), 0,
            "Counteroffers fix pay but not the reasons you looked elsewhere, and some managers see you as a flight risk afterwards. Decide what you really want before you start talks.",
            source = "Morph Academy"),
        concept("ea-negotiate-script", T, 3, "An employer asks for your expected salary first. What's a strong way to answer?",
            "Give a researched range with your target at the bottom, and tie it to the role: \"For this scope, roles like this pay Ksh 140k–160k.\" Or ask their budget first. Avoid naming your current pay as your ceiling.",
            source = "Morph Academy"),
        quiz("ea-ajira", T, 3, "Which Kenyan government programme trains young people for online and digital work?",
            listOf("Ajira Digital", "Boma Yangu", "Hustler Fund", "Linda Jamii"), 0,
            "Ajira Digital, run by the ICT ministry since 2016, offers training and mentorship for online work. Boma Yangu is housing; the Hustler Fund gives small loans.",
            source = "Ministry of ICT, Kenya"),
        concept("ea-fx-income", T, 3, "You earn in US dollars online but spend in shillings. What's the hidden risk and upside?",
            "When the shilling weakens, your dollars buy more shillings; when it strengthens (as in 2024), your shilling income falls even if your rate stays the same. Budget on a cautious rate and watch withdrawal fees.",
            source = "CBK exchange rates, 2024", timeSensitive = true),
        quiz("ea-cut-vs-earn-hours", T, 3, "You earn Ksh 500 an hour. Is a 2-hour trip to save Ksh 600 on groceries worth it, purely in money?",
            listOf("No: your time is worth Ksh 1,000", "Yes: you save Ksh 600", "Yes, always save money", "Only if you go by matatu"), 0,
            "Two hours at Ksh 500 equals Ksh 1,000, more than the Ksh 600 saved. This only holds if you could really earn in that time. Free hours may be worth less.",
            source = "Morph Academy"),

        // ---------- Level 4: Shark ----------
        quiz("ea-paye-bands", T, 4, "Kenya's top PAYE rate is 35%. Above roughly what monthly taxable pay does it start?",
            listOf("Ksh 800,000", "Ksh 500,000", "Ksh 100,000", "Ksh 32,333"), 0,
            "Monthly bands: 10% to Ksh 24,000, 25% to 32,333, 30% to 500,000, 32.5% to 800,000 and 35% above, less a Ksh 2,400 personal relief. A 2026 push to change them was not enacted.",
            source = "Finance Act 2023; KRA, 2026", timeSensitive = true),
        quiz("ea-marginal-raise", T, 4, "You earn Ksh 150,000 gross and get a Ksh 10,000 raise. After SHIF, Housing Levy and 30% PAYE, about how much more do you take home?",
            listOf("About Ksh 6,700", "About Ksh 7,000", "About Ksh 9,000", "About Ksh 5,000"), 0,
            "SHIF 2.75% (275) and Levy 1.5% (150) come off first and are deductible, so tax is 30% of 9,575 ≈ 2,873. You keep about Ksh 6,700. NSSF is already maxed at this pay.",
            source = "KRA, 2026", timeSensitive = true),
        concept("ea-marginal-vs-average", T, 4, "What's the difference between your marginal and average tax rate?",
            "Marginal is the rate on your next shilling (30% for most salaried Kenyans). Average is total tax ÷ total pay, always lower because early bands are taxed at 10% and 25%. A raise never cuts your take-home pay; only the extra is taxed higher.",
            source = "KRA, 2026", timeSensitive = true),
        quiz("ea-pension-shield", T, 4, "How much can you put into a registered pension scheme each month and deduct before PAYE?",
            listOf("Up to Ksh 30,000", "Up to Ksh 5,000", "Up to Ksh 100,000", "Nothing is deductible"), 0,
            "Since December 2024 contributions up to Ksh 30,000 a month (360,000 a year) are deductible. At a 30% marginal rate, each Ksh 10,000 saved this way cuts PAYE by about Ksh 3,000.",
            source = "KRA notice, Tax Laws (Amendment) Act 2024", timeSensitive = true),
        quiz("ea-nssf-2026", T, 4, "From February 2026, what's the most an employee pays into NSSF each month?",
            listOf("Ksh 6,480", "Ksh 2,160", "Ksh 12,960", "Ksh 1,080"), 0,
            "6% of pay up to an upper limit of Ksh 108,000 = Ksh 6,480, matched by the employer (Ksh 12,960 in total). The lower limit is Ksh 9,000.",
            source = "NSSF Act 2013, Year 4 rates (PwC, 2026)", timeSensitive = true,
            tryThis = "Check your NSSF statement on the NSSF app or portal."),
        concept("ea-employment-act-basics", T, 4, "Under Kenya's Employment Act, what leave are you entitled to?",
            "At least 21 working days of paid annual leave after 12 months; 3 months' paid maternity leave; 2 weeks' paid paternity leave; and after 2 months' service, 7 days' sick leave on full pay then 7 on half pay.",
            source = "Employment Act 2007, ss. 28–30"),
        quiz("ea-notice", T, 4, "If you're paid monthly and your contract is silent, how much notice must either side give to end it?",
            listOf("28 days", "7 days", "3 months", "None"), 0,
            "For pay at monthly intervals, the Employment Act sets 28 days' written notice, or pay in lieu. Contracts can give more, not less.",
            source = "Employment Act 2007, s. 35"),
        quiz("ea-redundancy", T, 4, "If you're declared redundant after 6 full years, what's the minimum severance pay?",
            listOf("90 days' pay", "6 days' pay", "1 month's pay", "6 months' pay"), 0,
            "The Act sets at least 15 days' pay for each completed year of service: 15 × 6 = 90 days. Notice and any unpaid leave are paid on top.",
            source = "Employment Act 2007, s. 40"),
        concept("ea-written-contract", T, 4, "When must your employer give you a written contract, and how long can probation last?",
            "Any job longer than 3 months needs a written contract. Probation can't exceed 6 months, extendable by up to 6 more only with your agreement. During probation, either side can end it with 7 days' notice.",
            source = "Employment Act 2007, ss. 9, 42"),
        concept("ea-career-capital", T, 4, "What does Cal Newport mean by \"career capital\"?",
            "Rare and valuable skills you build through deliberate practice. You trade them for pay, freedom and interesting work. His point: passion often follows mastery, so build skills first instead of waiting to find your passion.",
            source = "Newport, So Good They Can't Ignore You, 2012"),
        concept("ea-skill-stack", T, 4, "What is a \"skill stack\", and why can it beat being world-class at one thing?",
            "Combine several good-but-not-elite skills that rarely appear together, say accounting + Python + Kiswahili copywriting. Few people match the mix, so you face less competition and can charge more.",
            source = "Scott Adams, 2013"),
        quiz("ea-shif-deductible", T, 4, "Which payroll deduction did the Tax Laws (Amendment) Act 2024 make deductible before PAYE?",
            listOf("SHIF and the Housing Levy", "M-Pesa charges", "Chama contributions", "Matatu fare"), 0,
            "From December 2024, SHIF (2.75%) and the Affordable Housing Levy (1.5%) are deducted before PAYE is calculated, so you pay less tax on them.",
            source = "KRA notice, 2024", timeSensitive = true),

        // ---------- Level 5: Legend ----------
        concept("ea-mincer", T, 5, "What does Jacob Mincer's earnings equation (1974) say about how pay grows over a career?",
            "Log pay rises with years of schooling and with experience, but experience gains slow down over time (a curve, not a line). So the steepest pay growth is early in your career, when learning on the job pays most.",
            source = "Mincer, Schooling, Experience and Earnings, 1974"),
        quiz("ea-returns-education", T, 5, "A review of 1,120 estimates in 139 countries found each extra year of schooling raises pay by roughly...",
            listOf("9%", "1%", "25%", "50%"), 0,
            "Psacharopoulos and Patrinos found a private return of about 9% a year of schooling, stable over decades, and higher in low-income countries and for women.",
            source = "Psacharopoulos & Patrinos, 2018"),
        quiz("ea-leibbrandt-list", T, 5, "In Leibbrandt & List's field experiment, what happened to the gender gap in negotiating when job ads said pay was negotiable?",
            listOf("It disappeared, even reversed", "It doubled", "Nothing changed", "Men stopped applying"), 0,
            "With no signal, men negotiated more. When ads stated wages were negotiable, women negotiated as much or more. Ambiguity, not ability, drove the gap.",
            source = "Leibbrandt & List, Management Science, 2015"),
        concept("ea-women-dont-ask", T, 5, "What did Babcock & Laschever's \"Women Don't Ask\" (2003) highlight?",
            "In their studies, men were far more likely than women to negotiate starting pay. Small early gaps compound: every later raise is a percentage of a lower base. Later research added that social backlash, not just reluctance, explains part of it.",
            source = "Babcock & Laschever, 2003"),
        concept("ea-goldin", T, 5, "What did Claudia Goldin's work (Nobel Prize 2023) show about the gender pay gap?",
            "Much of today's gap is within the same occupation and widens after the first child. \"Greedy jobs\" pay disproportionately for long, inflexible hours, which caregivers can less often give.",
            source = "Goldin, 2014; Nobel Committee, 2023"),
        quiz("ea-switcher-reversal", T, 5, "In early 2025, US job stayers briefly out-earned switchers for the first time since 2010. What does that teach?",
            listOf("The switch premium depends on hiring demand", "Switching never pays", "Stayers always win", "Wages stopped growing"), 0,
            "The premium for switching is big in tight labour markets (it peaked in 2022) and shrinks when hiring cools. Read the market before you jump.",
            source = "Atlanta Fed Wage Growth Tracker, 2025", timeSensitive = true),
        quiz("ea-kenya-gig", T, 5, "A 2020 Mastercard study estimated how many Kenyans did online gig work?",
            listOf("About 36,600", "About 5,000", "About 2 million", "About 500,000"), 0,
            "The Mastercard white paper estimated 36,573 online gig workers earning about USD 109 million a year, far fewer than offline gig workers like boda riders and casuals.",
            source = "Mastercard, The Gig Economy in East Africa, 2020"),
        concept("ea-ilo-platforms", T, 5, "What did the ILO's 2021 report find about digital labour platforms?",
            "Platforms grew about fivefold from 2010 to 2020 (from about 142 to over 777). Workers gain flexibility and access to global clients, but often face low pay after fees, unpaid time hunting for tasks, and no social protection.",
            source = "ILO, World Employment and Social Outlook, 2021"),
        concept("ea-superstars", T, 5, "Why do the top few earners in some fields earn many times more than the merely good?",
            "Sherwin Rosen's \"economics of superstars\" (1981): when one person's work can reach huge audiences cheaply (music, software, online courses), small talent gaps become huge pay gaps. Digital work makes more fields like this.",
            source = "Rosen, 1981"),
        concept("ea-signalling", T, 5, "If certificates don't always teach new skills, why do employers pay for them?",
            "Michael Spence's signalling theory (1973): a costly credential signals traits like persistence and ability that are hard to see. Part of a certificate's value is the signal, which is why its brand and difficulty matter.",
            source = "Spence, 1973"),
        concept("ea-child-penalty", T, 5, "What is the \"child penalty\" in earnings research?",
            "Kleven, Landais and Søgaard (2019) found Danish women's earnings fell about 20% for the long run after a first child, while men's barely moved. It now explains most of the remaining gender gap in Denmark.",
            source = "Kleven, Landais & Søgaard, 2019"),
        you("ea-you-freedom-earn", T, 5, "Your freedom number is about {freedom_number}, and your savings rate is {savings_rate}. Which lever moves it fastest?",
            "A raise saved in full lifts your savings rate without cutting your lifestyle, and if spending stays flat your freedom number stays put. Earning more and saving the difference is the fastest route most research finds.",
            tryThis = "Plan where your next raise goes before it arrives.", action = Action.AUTOSORT,
            signals = setOf(Signal.MONEY_IN_RECENT)),
    )
}
